import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"重要人物と組織","description":"","frontmatter":{},"headers":[],"relativePath":"ja/95-关键人物与组织.md","filePath":"ja/95-关键人物与组织.md"}'),e={name:"ja/95-关键人物与组织.md"};function o(l,t,i,b,n,_){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="重要人物と組織" tabindex="-1">重要人物と組織 <a class="header-anchor" href="#重要人物と組織" aria-label="Permalink to &quot;重要人物と組織&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>95</td></tr><tr><td>所属モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>重要人物、重要組織、歴史的役割、機関の職能、共生文明</td></tr></tbody></table><h2 id="一、説明" tabindex="-1">一、説明 <a class="header-anchor" href="#一、説明" aria-label="Permalink to &quot;一、説明&quot;">​</a></h2><p>本文書はアンカー共生文明の発展過程における重要人物と重要組織を収録し、歴史時期と組織タイプによって分類・編成されている。重要人物の部分では人物名、時期、核心的貢献、歴史的地位を記載し；重要組織の部分では組織名、設立時間、核心的職能、歴史的役割を記載している。本文書は動的更新文書であり、歴史の推進と組織の変遷に伴い、継続的に補充・修正される。</p><h2 id="二、重要人物" tabindex="-1">二、重要人物 <a class="header-anchor" href="#二、重要人物" aria-label="Permalink to &quot;二、重要人物&quot;">​</a></h2><h3 id="_2-1-前アンカー時代の思想先駆者" tabindex="-1">2.1 前アンカー時代の思想先駆者 <a class="header-anchor" href="#_2-1-前アンカー時代の思想先駆者" aria-label="Permalink to &quot;2.1 前アンカー時代の思想先駆者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名</th><th>時期</th><th>核心的貢献</th><th>歴史的地位</th></tr></thead><tbody><tr><td>玄衡子</td><td>約-5億年</td><td>略奪式修練体系を体系的に反省した最初の思想家、「共生」概念の原型を提唱、『反略奪論』残巻の著者</td><td>共生思想の太古の先駆者、その思想は数億年の沈黙の後、アンカー共生文明の精神的源となった</td></tr><tr><td>万霊母</td><td>約-1億年</td><td>最初の大規模共生実験的文明を指導、最終的に略奪式文明によって破壊されたものの、その実践は共生体系の実行可能性を証明した</td><td>共生実践の先行者、後世に「共生の母」として尊崇される</td></tr><tr><td>锚覚者</td><td>約-1万年</td><td>第一位面の修練者、長期修練の中で偶然法則ネットワーク中の安定ノードを感知、アンカーメカニズムを発見</td><td>アンカーメカニズムの発見者、アンカー覚醒紀元の開啓者</td></tr></tbody></table><h3 id="_2-2-アンカー覚醒紀元の奠基者" tabindex="-1">2.2 アンカー覚醒紀元の奠基者 <a class="header-anchor" href="#_2-2-アンカー覚醒紀元の奠基者" aria-label="Permalink to &quot;2.2 アンカー覚醒紀元の奠基者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名</th><th>時期</th><th>核心的貢献</th><th>歴史的地位</th></tr></thead><tbody><tr><td>锚定公</td><td>-10000年から-9200年</td><td>锚覚者の弟子、アンカーメカニズムを体系的に研究、最初の人工アンカーを建設、『アンカー原理』の著者</td><td>アンカー技術の奠基者、人工アンカーの発明者</td></tr><tr><td>共生子</td><td>-6000年から-5100年</td><td>アンカー技術と共生思想を結合、「アンカー共生」理論体系を創立、『アンカー共生論』の著者</td><td>アンカー共生理論の創立者、共生文明の思想導師</td></tr><tr><td>衡元公</td><td>-5000年から-4300年</td><td>アンカーを基礎とする最初の共生型城邦「衡元城」を建設、略奪式文明の攻撃を成功裏に撃退</td><td>最初の共生型城邦の建設者、共生制度の実践者</td></tr><tr><td>万族使</td><td>-2000年から-1200年</td><td>最初の「万族共生大会」を発起、数十の種族の間を奔走して共生連合を提唱</td><td>万族連合の提唱者、跨種族共生の先駆者</td></tr></tbody></table><h3 id="_2-3-共生体系建立期の建国者" tabindex="-1">2.3 共生体系建立期の建国者 <a class="header-anchor" href="#_2-3-共生体系建立期の建国者" aria-label="Permalink to &quot;2.3 共生体系建立期の建国者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名</th><th>時期</th><th>核心的貢献</th><th>歴史的地位</th></tr></thead><tbody><tr><td>立宪公</td><td>-1000年から-900年</td><td>共生憲法起草委員会主席、『共生憲法』の起草を主宰、憲法の全民公投通過を推進</td><td>共生憲法の主要起草者、共生文明の憲法之父</td></tr><tr><td>执法公</td><td>-900年から-780年</td><td>第一任共生執行委員会主席、共生文明の行政体系と法律執行メカニズムの建設を主宰</td><td>共生行政体系の建設者、第一任行政首脳</td></tr><tr><td>司法母</td><td>-900年から-800年</td><td>第一任共生法院首席大法官、共生文明の司法体系と違憲審査制度を建設</td><td>共生司法体系の建設者、第一任司法首脳</td></tr><tr><td>三百師</td><td>-500年から-300年</td><td>三百套本源修練体系の発掘と整理作業を主宰、チームを率いて全部三百套体系の検証を完成</td><td>三百套体系の総整理者、修練開放の工程総指揮</td></tr><tr><td>倍增公</td><td>-300年から-220年</td><td>倍增果実の技術化応用研究を主宰、百倍推演増幅技術の工程化突破を実現</td><td>倍增果実技術化の首席科学者、推演迭代体系の推進者</td></tr></tbody></table><h3 id="_2-4-開放と活性化期の指導者" tabindex="-1">2.4 開放と活性化期の指導者 <a class="header-anchor" href="#_2-4-開放と活性化期の指導者" aria-label="Permalink to &quot;2.4 開放と活性化期の指導者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名</th><th>時期</th><th>核心的貢献</th><th>歴史的地位</th></tr></thead><tbody><tr><td>開放公</td><td>-100年から-50年</td><td>三百套本源修練体系の全面開放作業を主宰、修練資源配給制度と導師ネットワークを建設</td><td>三百套体系開放の総指揮、「人人有路」の実践者</td></tr><tr><td>活性化公</td><td>-50年から元年</td><td>20%活性化戦略の実施を主宰、チームを率いて50年以内に20%衆生の活性化目標を完成</td><td>20%活性化戦略の総指揮、共生文明新紀元の開啓者</td></tr><tr><td>昇維公</td><td>元年から80年</td><td>初回昇維工程を主宰、四階段昇維路径の実施を推進、初回段階的昇維を実現</td><td>初回昇維の総工程師、昇維紀元の指導者</td></tr></tbody></table><h3 id="_2-5-万族共和と跨位面時代の探索者" tabindex="-1">2.5 万族共和と跨位面時代の探索者 <a class="header-anchor" href="#_2-5-万族共和と跨位面時代の探索者" aria-label="Permalink to &quot;2.5 万族共和と跨位面時代の探索者&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人物名</th><th>時期</th><th>核心的貢献</th><th>歴史的地位</th></tr></thead><tbody><tr><td>万族共主</td><td>100年から200年</td><td>万族共和の成立作業を主宰、万族名簿編纂と跨種族融合政策を推進</td><td>万族共和の締造者、第一任万族共主</td></tr><tr><td>位面母</td><td>500年から650年</td><td>第一任位面管理局局長、大規模跨位面探索計画を主宰、位面座標総庫を建設</td><td>跨位面探索の開拓者、位面管理体系の建設者</td></tr><tr><td>考古公</td><td>800年から950年</td><td>複製鏡異地考古方案の最終成熟を主宰、跨位面考古を規模化時代に推進</td><td>考古方案の集大成者、跨位面考古の奠基者</td></tr><tr><td>時律公</td><td>1000年から1150年</td><td>時間遡及技術の突破を主宰、先観測後有限干渉準則の確立を推進</td><td>時間遡及技術の指導者、時間法則準則の制定者</td></tr></tbody></table><h2 id="三、重要組織" tabindex="-1">三、重要組織 <a class="header-anchor" href="#三、重要組織" aria-label="Permalink to &quot;三、重要組織&quot;">​</a></h2><h3 id="_3-1-最高権力機構" tabindex="-1">3.1 最高権力機構 <a class="header-anchor" href="#_3-1-最高権力機構" aria-label="Permalink to &quot;3.1 最高権力機構&quot;">​</a></h3><table tabindex="0"><thead><tr><th>組織名</th><th>設立時間</th><th>核心的職能</th><th>歴史的役割</th></tr></thead><tbody><tr><td>アンカー議事会</td><td>-900年</td><td>共生文明最高権力機構、万族代表により比例構成、立法権と重大事項決定権を行使</td><td>共生文明の最高決策機構、すべての重大法律と戦略の制定者</td></tr><tr><td>共生執行委員会</td><td>-900年</td><td>共生文明最高行政機構、憲法と法律の執行、日常治理を担当</td><td>共生文明の最高行政機関、法律と政策の執行者</td></tr><tr><td>共生法院</td><td>-900年</td><td>共生文明最高司法機構、独立して審判権を行使、違憲審査と重大案件審理を担当</td><td>共生文明の最高司法機関、法治の守護者</td></tr><tr><td>アンカー監督委員会</td><td>-900年</td><td>独立監督機構、すべての権力機構に対する監督を担当、権力濫用を防止</td><td>共生文明の独立監督機関、権力制衡の重要な一環</td></tr></tbody></table><h3 id="_3-2-専門管理機構" tabindex="-1">3.2 専門管理機構 <a class="header-anchor" href="#_3-2-専門管理機構" aria-label="Permalink to &quot;3.2 専門管理機構&quot;">​</a></h3><table tabindex="0"><thead><tr><th>組織名</th><th>設立時間</th><th>核心的職能</th><th>歴史的役割</th></tr></thead><tbody><tr><td>位面管理局</td><td>500年</td><td>位面座標総庫の維持、穿梭許可審査、跨位面考古管理、跨位面外交調整を担当</td><td>跨位面交互の主管機構、位面探索の管理者</td></tr><tr><td>時間法則委員会</td><td>1000年</td><td>時間遡及操作の審査、時間法則研究、時間悖論防控監督を担当</td><td>時間遡及操作の審査と監督機構、時間法則安全の守護者</td></tr><tr><td>時間法則審計委員会</td><td>1050年</td><td>時間遡及操作の事後審計を担当、制御不能な時間線擾乱を引き起こしていないことを確認</td><td>時間操作の独立審計機構、時間遡及安全の最後の防線</td></tr><tr><td>跨位面倫理委員会</td><td>600年</td><td>跨位面倫理準則の制定と解釈、高リスク跨位面交互プロジェクトの審査、倫理違反訴状の受理</td><td>跨位面交互の倫理監督機構、文明主体性の守護者</td></tr><tr><td>知識回伝審計処</td><td>850年</td><td>知識回伝操作の審計を担当、回伝内容が「僅回伝知識」原則に適合することを確認</td><td>知識回伝の審計機構、跨位面汚染防控の重要な一環</td></tr></tbody></table><h3 id="_3-3-研究と教育機構" tabindex="-1">3.3 研究と教育機構 <a class="header-anchor" href="#_3-3-研究と教育機構" aria-label="Permalink to &quot;3.3 研究と教育機構&quot;">​</a></h3><table tabindex="0"><thead><tr><th>組織名</th><th>設立時間</th><th>核心的職能</th><th>歴史的役割</th></tr></thead><tbody><tr><td>アンカー研究院</td><td>-8000年</td><td>アンカーメカニズムの基礎研究と応用開発、人工アンカーの建設と維持</td><td>アンカー技術の核心研究機構、共生文明の技術源の一つ</td></tr><tr><td>三百套体系整理委員会</td><td>-500年</td><td>三百套本源修練体系の発掘、整理、検証と持続的最適化</td><td>三百套体系の整理と維持機構、修練開放の技術支撑</td></tr><tr><td>共生大学連盟</td><td>-700年</td><td>高等教育と修練教育の連合組織、高級人材育成と学術研究を担当</td><td>共生文明の最高学府連盟、人材育成と学術革新の核心</td></tr><tr><td>跨位面考古学院</td><td>550年</td><td>跨位面考古専門人材を育成、考古技術研究と方法論革新を展開</td><td>跨位面考古の人材育成と技術研究開発センター</td></tr><tr><td>時間法則研究所</td><td>950年</td><td>時間法則の基礎理論研究と時間遡及技術の研究開発</td><td>時間法則研究の核心機構、時間遡及技術の発祥地</td></tr></tbody></table><h3 id="_3-4-軍事と安全組織" tabindex="-1">3.4 軍事と安全組織 <a class="header-anchor" href="#_3-4-軍事と安全組織" aria-label="Permalink to &quot;3.4 軍事と安全組織&quot;">​</a></h3><table tabindex="0"><thead><tr><th>組織名</th><th>設立時間</th><th>核心的職能</th><th>歴史的役割</th></tr></thead><tbody><tr><td>共生防御軍</td><td>-850年</td><td>共生文明の正規防御力量、位面防御と外部脅威対応を担当</td><td>共生文明の主要軍事力量、国家安全の擁護者</td></tr><tr><td>位面巡邏隊</td><td>520年</td><td>探知済み位面の巡邏と安全監視を担当、跨位面安全事件に対応</td><td>跨位面安全の一線力量、位面秩序の維持者</td></tr><tr><td>法則汚染応急隊</td><td>600年</td><td>法則汚染とエネルギー汚染事件の応急対応と汚染除去を担当</td><td>法則汚染の応急処置力量、宇宙環境の守護者</td></tr><tr><td>時間悖論応急組</td><td>1020年</td><td>時間悖論事件の応急対応と因果修復操作を担当</td><td>時間悖論の応急処置力量、時間線安定の最後の保障</td></tr></tbody></table><h3 id="_3-5-民間と社会組織" tabindex="-1">3.5 民間と社会組織 <a class="header-anchor" href="#_3-5-民間と社会組織" aria-label="Permalink to &quot;3.5 民間と社会組織&quot;">​</a></h3><table tabindex="0"><thead><tr><th>組織名</th><th>設立時間</th><th>核心的職能</th><th>歴史的役割</th></tr></thead><tbody><tr><td>万族共生大会</td><td>-2000年</td><td>万族代表の定期集会、跨種族共生事務を討論、文化交流を促進</td><td>万族交流の重要なプラットフォーム、万族共和の前身組織</td></tr><tr><td>修練者協会</td><td>-600年</td><td>修練者の業界自治組織、修練者権益維護、業界規範制定を担当</td><td>修練者の自治組織、修練業界規範化の推進者</td></tr><tr><td>消費者協会</td><td>-650年</td><td>消費者権益保護組織、消費権益擁護、消費教育、社会監督を担当</td><td>消費者権益の代弁者、市場秩序の社会監督者</td></tr><tr><td>環境保護連盟</td><td>-550年</td><td>環境保護の民間連合組織、環境監督、環境教育、生態修復ボランティア活動を担当</td><td>環境保護の社会力量、宇宙生態文明の推進者</td></tr><tr><td>跨位面友好協会</td><td>580年</td><td>跨位面文明友好交流を促進する民間組織、民間外交、文化交流を担当</td><td>跨位面民間外交の核心力量、文明間理解の架け橋</td></tr></tbody></table><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>重要人物と組織はアンカー共生文明の歴史の生きた担い手である。太古の思想先駆者から現代の文明指導者まで、最高権力機構から民間社会組織まで、すべての人物と組織が共生文明の壮大な物語の中で代替不可能な役割を演じている。彼らの奮闘と貢献が共同で、アンカー共生文明が無から有へ、小から大へ、本位面から全宇宙へと至る壮麗な叙事詩を織り上げている。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>70-紀元区分総表</li><li>49-治理框架と権力制衡</li><li>77-万族共和成立</li></ul>',30)])])}const u=d(e,[["render",o]]);export{c as __pageData,u as default};
